import { Kysely } from 'kysely'
import { afterAll, beforeAll, beforeEach, describe, expect, it } from 'vitest'
import { f, resource, where } from '@protobase/schema'
import { createAdmin } from '../src/index'
import { signTestToken, testAuthenticator } from '../../../test-support/server'
import { openSnapshotDb, type SnapshotDb } from '../../../test-support/sql-snapshot'

// A workspace chat whose direct message is unique per set of members: `member_key`, generated by the database from
// `member_ids`, sorted and without repeats. Starting one again opens the one there is, for a caller who reads it.

const directMessage = (name: string) =>
  resource(name)
    .table('direct_messages')
    .fields({
      id: f.integer().readOnly().filterable().sortable().dbDefault(),
      tenant_id: f.integer().readOnly(),
      member_ids: f.json(),
      topic: f.text().optional(),
      member_key: f.text().readOnly().dbDefault(),
    })
    .primaryKey((r) => r.id)
    .tenant((r) => r.tenant_id)
    .access({ read: (ctx) => where.has('member_ids', ctx.user!.id as string) })

const directMessages = directMessage('direct_messages').openExisting((r) => [r.tenant_id, r.member_key])
// The same table without the option, as every resource answers a unique conflict
const plainDirectMessages = directMessage('plain_direct_messages')

// No unique index has exactly these columns
const misnamed = directMessage('misnamed_direct_messages').openExisting((r) => [r.member_key])

// A handle is unique across every workspace, so a create can run into another workspace's
const handles = resource('handles')
  .table('handles')
  .fields({ id: f.integer().readOnly().filterable().sortable().dbDefault(), tenant_id: f.integer().readOnly(), handle: f.text() })
  .primaryKey((r) => r.id)
  .tenant((r) => r.tenant_id)
  .openExisting((r) => [r.handle])

const channels = resource('channels')
  .table('channels')
  .fields({ id: f.integer().filterable().sortable(), tenant_id: f.integer().readOnly(), member_ids: f.json() })
  .primaryKey((r) => r.id)
  .tenant((r) => r.tenant_id)
  .access({ read: (ctx) => where.has('member_ids', ctx.user!.id as string) })

// A topic's name is unique in the workspace, and a topic is read by whoever reads its channel
const topics = resource('topics')
  .table('topics')
  .fields({ id: f.integer().readOnly().filterable().sortable().dbDefault(), tenant_id: f.integer().readOnly(), channel_id: f.relation('channels').filterable(), name: f.text() })
  .primaryKey((r) => r.id)
  .tenant((r) => r.tenant_id)
  .parent((r) => r.channel_id, 'read')
  .openExisting((r) => [r.tenant_id, r.name])

let pg: SnapshotDb
let db: Kysely<any>
let app: ReturnType<typeof createAdmin>
const unhandled: unknown[] = []
beforeAll(async () => {
  pg = await openSnapshotDb('empty')
  await pg.exec(`
    create function member_key(members jsonb) returns text immutable language sql
      as $$ select string_agg(distinct member, ',' order by member) from jsonb_array_elements_text(members) member $$;
    create table direct_messages (id integer generated always as identity primary key, tenant_id integer not null, member_ids jsonb not null,
      topic text unique, member_key text generated always as (member_key(member_ids)) stored, unique (tenant_id, member_key));
    create index on direct_messages using gin (member_ids);
    create table handles (id integer generated always as identity primary key, tenant_id integer not null, handle text not null unique);
    create table channels (id integer primary key, tenant_id integer not null, member_ids jsonb not null);
    create index on channels using gin (member_ids);
    create table topics (id integer generated always as identity primary key, tenant_id integer not null, channel_id integer not null references channels, name text not null,
      unique (tenant_id, name));
    create index on topics (channel_id);
  `)
  db = new Kysely({ dialect: pg.dialect })
  app = createAdmin({
    resources: [directMessages, plainDirectMessages, misnamed, handles, channels, topics],
    db,
    authenticate: testAuthenticator,
    options: { onUnhandledError: (error) => { unhandled.push(error) } },
  })
})
afterAll(async () => { await db.destroy() })

beforeEach(async () => {
  await pg.exec(`
    truncate direct_messages, handles, topics, channels restart identity;
    insert into direct_messages (tenant_id, member_ids, topic) values (1, '["bob", "alice"]', 'lunch');
    insert into handles (tenant_id, handle) values (1, 'alice');
    insert into channels values (1, 1, '["alice", "bob"]'), (2, 1, '["alice"]');
    insert into topics (tenant_id, channel_id, name) values (1, 2, 'plans');
  `)
})

const create = async (resource: string, sub: string, body: unknown, tenant = 1) => {
  const headers = { authorization: `Bearer ${signTestToken({ sub, roles: ['member'], tenant })}`, 'content-type': 'application/json' }
  const response = await app.request(`/api/v1/${resource}`, { method: 'POST', headers, body: JSON.stringify(body) })
  return { status: response.status, body: await response.json() }
}

const plainConflict = {
  type: 'urn:protobase:problem:conflict',
  title: 'Conflict',
  status: 409,
  detail: 'A record with the same unique value already exists',
}

describe('a create refused by the unique key of .openExisting()', () => {
  it('names the record holding those values to a caller who reads it', async () => {
    const answer = await create('direct_messages', 'alice', { member_ids: ['alice', 'bob', 'alice'] })
    expect(answer).toEqual({ status: 409, body: { ...plainConflict, instance: '/api/v1/direct_messages', existing: { key: '1' } } })
  })

  it('answers a caller who cannot read that record as if the resource had no option', async () => {
    const outside = await create('direct_messages', 'carol', { member_ids: ['bob', 'alice'] })
    const plain = await create('plain_direct_messages', 'carol', { member_ids: ['bob', 'alice'] })
    expect(outside).toEqual({ status: 409, body: { ...plainConflict, instance: '/api/v1/direct_messages' } })
    expect(plain).toEqual({ status: 409, body: { ...plainConflict, instance: '/api/v1/plain_direct_messages' } })
  })

  it('names no record of another workspace', async () => {
    const answer = await create('handles', 'alice', { handle: 'alice' }, 2)
    expect(answer).toEqual({ status: 409, body: { ...plainConflict, instance: '/api/v1/handles' } })
    expect((await create('handles', 'alice', { handle: 'alice' })).body.existing).toEqual({ key: '1' })
  })

  it('names no record whose parent the caller does not read', async () => {
    expect((await create('topics', 'bob', { channel_id: 1, name: 'plans' })).body).toEqual({ ...plainConflict, instance: '/api/v1/topics' })
    expect((await create('topics', 'alice', { channel_id: 1, name: 'plans' })).body.existing).toEqual({ key: '1' })
  })

  it('names no record for a conflict on another unique key', async () => {
    const answer = await create('direct_messages', 'alice', { member_ids: ['alice', 'carol'], topic: 'lunch' })
    expect(answer).toEqual({ status: 409, body: { ...plainConflict, instance: '/api/v1/direct_messages' } })
  })

  it('creates a record whose values no record holds yet', async () => {
    const answer = await create('direct_messages', 'alice', { member_ids: ['carol', 'alice'] })
    expect(answer.status).toBe(201)
    expect(answer.body).toMatchObject({ member_ids: ['carol', 'alice'], member_key: 'alice,carol' })
  })

  it('answers a resource without the option as before', async () => {
    const answer = await create('plain_direct_messages', 'alice', { member_ids: ['alice', 'bob'] })
    expect(answer).toEqual({ status: 409, body: { ...plainConflict, instance: '/api/v1/plain_direct_messages' } })
  })

  it('fails with an error naming the resource when no unique index has exactly its fields', async () => {
    expect((await create('misnamed_direct_messages', 'alice', { member_ids: ['alice', 'bob'] })).status).toBe(500)
    expect(unhandled.map((error) => (error as Error).message)).toEqual(['The openExisting fields of misnamed_direct_messages (member_key) are not the columns of a unique index of its table'])
  })
})
